296	// ---- shape brushes (curved forms; massing) — the model picks parameters, code draws the form ---------------------
297	export * from "./shapes-curved.mjs";
298	export * from "./shapes-massing.mjs";
299	
300	// ---- landscaping brushes (terrain, strata, boulders, water, trees, paths, bridges) — see references/landscaping.md --
301	export * from "./terrain.mjs";
302	
303	// ---- roofs by style name (gable, hip, pyramid, mansard, gambrel, flat-parapet, shed, dutch-gable) — references/roofs.md
304	export * from "./roofs.mjs";
305	
306	// ---- facade brushes (signage, pilasters, surrounds, glazing, fixtures, planters) — references/detail-language.md -----
307	// Each is a function on a grid (writes only where it may: air for projections, plain wall for in-place trim; returns
308	// { cells, skipped, notes, info }) and a B.* twin that returns the plan as g.set argument lists, unchecked.
309	// at = a wall cell (bottom-left of the band / opening as seen from outside), face = the side it looks out of.
310	import { commitGrid, lookGrid, tuples } from "./brush-core.mjs";
311	import { plaquePlan, signboardPlan, buntingPlan, bannerWordPlan } from "./brush-sign.mjs";
312	import { clockPlan } from "./brush-clock.mjs";
313	export { trussPlan } from "./roof-trusses.mjs";
314	import { pilasterPlan } from "./brush-pilaster.mjs";
315	import { surroundPlan, glazingPlan } from "./brush-surround.mjs";
316	import { fixturePlan, planterPlan } from "./brush-fixture.mjs";
317	const withLook = (g, o) => ({ ...o, look: lookGrid(g), dataVersion: o?.dataVersion ?? g.dataVersion });
318	/** Lettering in a band: plaque(g, "LEAGUE HALL", { at, face, width, height, letter?, material?, frame?, style?, relief? }) */
319	export const plaque = (g, text, o) => commitGrid(g, plaquePlan(text, withLook(g, o)), o);
320	const STEP = { north: [0, -1], south: [0, 1], east: [1, 0], west: [-1, 0] };
321	/** A bed, both halves: foot at [x,y,z], the head one step toward facing (the pillow end), same colour and facing. */
322	export const bed = (g, [x, y, z], facing, color = "red") => {
323	  const [dx, dz] = STEP[facing] ?? STEP.north, b = `${color}_bed`;
324	  g.set(x, y, z, b, { facing, part: "foot", occupied: "false" });
325	  g.set(x + dx, y, z + dz, b, { facing, part: "head", occupied: "false" });
326	};
327	/** A window shutter: an open trapdoor in the cell in front of the wall (on the face side), lying flat against it.
328	 *  face: the way the wall looks (north for a north front); the trapdoor's facing is the face, so it lies on the wall. */
329	export const shutter = (g, [x, y, z], face, wood = "spruce", { height = 1 } = {}) => {
330	  for (let i = 0; i < height; i++) g.set(x, y + i, z, `${wood}_trapdoor`, { facing: face, half: "bottom", open: "true", powered: "false", waterlogged: "false" });
331	};
332	/** A word in banner letters hung on a board, in reading order for its face: bannerWord(g, "BUTCHER", { center: [14, 10, 4], face: "north" }). */
333	export const bannerWord = (g, word, o) => { let n = 0; for (const [x, y, z, ...b] of bannerWordPlan(word, { ...o, banner: B.banner })) if (!g.get(x, y, z) || /air$/.test(g.get(x, y, z).block)) { g.set(x, y, z, ...b); n++; } return n; };
334	/** Redstone shop sockets: layoutSockets({ face, at, floorY, units: "DS DS", rows }) -> the layout (as sockets.json) */
335	export { layoutSockets };
336	/** The sockets' fit-out (glass wall lines and back walls, spawn-proof pit floor, counters): fitSockets(g, layout, { counter, glass }) */
337	export const fitSockets = (g, layout, o) => { const t = socketFitout(layout, o); for (const c of t) g.set(...c); return t.length; };
338	/** A clock face on a tower: clock(g, { center, face, radius?: 2-4, dial?, bezel?, hands?, time?: "10:10", out?: 0|1 }) */
339	export const clock = (g, o) => commitGrid(g, clockPlan(withLook(g, o)), o);
340	/** A shop sign: signboard(g, "BAKERY", { at, face, mode: "wall"|"hanging", width?, height?, wood? }) */
341	export const signboard = (g, text, o) => commitGrid(g, signboardPlan(text, withLook(g, o)), o);
342	/** Banners along a row: bunting(g, { from, to, face, colors?, every?, pattern? }) */
343	export const bunting = (g, o) => commitGrid(g, buntingPlan(withLook(g, o)), o);
344	/** A profiled pilaster: pilaster(g, { at, face, height, width?, out?, material?, profile?, shoulder? }) */
345	export const pilaster = (g, o) => commitGrid(g, pilasterPlan(o), o);
346	/** An opening surround: surround(g, { at, face, width, height, preset?, trim?, keystone?, reveal?, door?, arch? }) */
347	export const surround = (g, o) => commitGrid(g, surroundPlan(withLook(g, o)), o);
348	/** Glazing: glazing(g, { at, face, width, height, preset: grid|shopfront|transom|sidelights, frame?, door? }) */
349	export const glazing = (g, o) => commitGrid(g, glazingPlan(withLook(g, o)), o);

